def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    def runs(edge):
        result = []
        i = 0
        while i < len(edge):
            if edge[i] == bg:
                i += 1
                continue
            color = edge[i]
            j = i + 1
            while j < len(edge) and edge[j] == color:
                j += 1
            result.append((i, j, color))
            i = j
        return result

    # Locate the matching pair of marked runs on opposite borders.
    candidates = []
    for orient, a, b in (
        ('v', grid[0], grid[-1]),
        ('h', [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]),
    ):
        ra, rb = runs(a), runs(b)
        for x in ra:
            for y in rb:
                if x[2] == y[2] and x[1]-x[0] == y[1]-y[0]:
                    candidates.append((orient, x, y))
    if not candidates:
        return [row[:] for row in grid]
    orient, first, second = max(candidates, key=lambda item: item[1][1] - item[1][0])
    start1, end1, marker = first
    start2, end2, _ = second
    length = end1 - start1
    bg_or_marker = {bg, marker}
    objs = [(r,c) for r in range(h) for c in range(w)
            if grid[r][c] not in bg_or_marker]
    if not objs:
        return [row[:] for row in grid]
    objcolors = {grid[r][c] for r,c in objs}
    raycolor = Counter(grid[r][c] for r,c in objs).most_common(1)[0][0]

    # The isolated objects mark which lanes in the paired edge runs are active.
    offsets = set()
    for r,c in objs:
        q = c if orient == 'v' else r
        if start1 <= q < end1:
            offsets.add(q-start1)
        if start2 <= q < end2:
            offsets.add(q-start2)
    if length == 2:
        offsets.update(range(length))
    if not offsets:
        offsets.update(range(length))

    out = [row[:] for row in grid]
    if orient == 'v':
        # top/bottom runs: each active column sends a ray inward
        for start, side in ((start1, 0), (start2, h-1)):
            for off in offsets:
                c = start + off
                dr = 1 if side == 0 else -1
                r = side + dr
                while 0 <= r < h if side == 0 else r >= 0:
                    val = grid[r][c]
                    if val == marker:
                        break
                    if val not in bg_or_marker:
                        out[r][c] = 4
                        break
                    out[r][c] = raycolor
                    r += dr
    else:
        # left/right runs: channels are indexed by row
        for start, side in ((start1, 0), (start2, w-1)):
            for off in offsets:
                r = start + off
                dc = 1 if side == 0 else -1
                c = side + dc
                while 0 <= c < w if side == 0 else c >= 0:
                    val = grid[r][c]
                    if val == marker:
                        break
                    if val not in bg_or_marker:
                        out[r][c] = 4
                        break
                    out[r][c] = raycolor
                    c += dc
    return out
